-- ════════════════════════════════════════════════════════════════════════
-- PROPUESTAS DE VIDEO · para elegir en el CRM, uno a uno
-- ════════════════════════════════════════════════════════════════════════
-- Dónde: Supabase del CRM → SQL Editor → pegar todo → Run.
--
-- NO CAMBIA NINGÚN VIDEO. Solo guarda candidatos (hasta 3 por ejercicio) en
-- la tabla de propuestas que ya usa el CRM. El video lo eliges TÚ con
-- «Usar este» en Entrenamiento → Galería:
--   · «👥 1 · Los usan ahora» (un toque filtra los que no tienen video) →
--     «🎬 Revisar videos uno a uno».
--   · «🔬 En análisis» → «🎬 Revisar videos uno a uno».
--
-- Ejercicios con propuestas:
--   ·  20 que usan hoy tus clientes y no tienen video
--   · 274 «en análisis» (los mismos de videos-en-analisis-2.sql)
--   717 propuestas en total. Canales primero, en el orden de siempre
--   (Functional Bodybuilding → PureGym → OPEX → Theory Library → LiveLean),
--   después YouTube general.
--
-- Va por ID de ejercicio. No borra nada: si una propuesta ya estaba, se deja
-- como está. Se puede correr dos veces. Estas salen primero en la ventana.
-- ════════════════════════════════════════════════════════════════════════
begin;

create table if not exists ejercicio_video_propuestas (
  id uuid primary key default gen_random_uuid(),
  ejercicio_id uuid not null references ejercicios(id) on delete cascade,
  orden int not null,
  ref text not null,
  titulo text,
  canal text,
  duracion_seg int,
  habla boolean,
  vertical boolean,
  created_at timestamptz default now(),
  unique (ejercicio_id, ref)
);
create index if not exists ejercicio_video_propuestas_ej_idx on ejercicio_video_propuestas (ejercicio_id, orden);
alter table ejercicio_video_propuestas enable row level security;
do $$
begin
  if not exists (select 1 from pg_policies where tablename = 'ejercicio_video_propuestas' and policyname = 'ejercicio_video_propuestas_coach') then
    create policy ejercicio_video_propuestas_coach on ejercicio_video_propuestas for all
      using (exists (select 1 from ejercicios e where e.id = ejercicio_id and e.user_id = auth.uid()))
      with check (exists (select 1 from ejercicios e where e.id = ejercicio_id and e.user_id = auth.uid()));
  end if;
end $$;

create temp table _p (ejercicio_id uuid, orden int, ref text, titulo text, canal text, duracion_seg int) on commit drop;

select p.ejercicio_id, p.orden, p.ref, p.titulo, p.canal, p.duracion_seg
  from _p p join ejercicios e on e.id = p.ejercicio_id
on conflict (ejercicio_id, ref) do nothing;

select count(distinct p.ejercicio_id) as ejercicios_con_propuestas,
       count(*) as propuestas_en_la_lista,
       count(*) filter (where e.id is null) as ejercicios_que_no_encontre
  from _p p left join ejercicios e on e.id = p.ejercicio_id;

commit;
